163	/**
164	 * Resolve deck keys through the practice cores first, then Atlas's prefix shards.
165	 * The complete index is deliberately reserved for a missing/broken shard manifest
166	 * or a shard lookup that cannot find an exact key: it is a compatibility fallback,
167	 * not the normal custom-deck transport.
168	 */
169	async function resolveDeckKeyMetadata(
170	  lemmaKeys: readonly string[],
171	  lexemes: readonly PracticeLexeme[],
172	  cache: Map<string, Promise<unknown>>,
173	): Promise<Map<string, DeckKeyResolution>> {
174	  const practiceByKey = practiceLexemesByKey(lexemes);
175	  const resolutions = new Map<string, DeckKeyResolution>();
176	  const unresolved: string[] = [];
177	
178	  for (const key of lemmaKeys) {
179	    const practice = keyLookupVariants(key)
180	      .map((variant) => practiceByKey.get(variant))
181	      .find((entry): entry is PracticeLexeme => Boolean(entry)) ?? null;
182	    resolutions.set(key, { practice, atlas: null });
183	    if (!practice) unresolved.push(key);
184	  }
185	
186	  // The common case is a deck entirely covered by the practice cores. Do not
187	  // download any Atlas index artifact in that case.
188	  if (unresolved.length === 0) return resolutions;
189	
190	  let rows: SearchRow[] = [];
191	  let needsFullIndexFallback = false;
192	  try {
193	    const manifest = await getShardJson<SearchShardManifest>('/lexicon/search-shards.json', cache);
194	    const shardPaths = Array.from(
195	      new Set(
196	        unresolved.flatMap((key) =>
197	          keyLookupVariants(key)
198	            .map((variant) => searchShardForQuery(manifest, variant)?.path)
199	            .filter((path): path is string => Boolean(path)),
200	        ),
201	      ),
202	    );
203	    if (shardPaths.length === 0) {
204	      needsFullIndexFallback = true;
205	    } else {
206	      rows = (await Promise.all(
207	        shardPaths.map((path) => getShardJson<SearchRow[]>(path, cache)),
208	      )).flat();
209	      const shardRowsByKey = searchRowsByKey(rows);
210	      needsFullIndexFallback = unresolved.some(
211	        (key) => !keyLookupVariants(key).some((variant) => shardRowsByKey.has(variant)),
212	      );
213	    }
214	  } catch {
215	    needsFullIndexFallback = true;
216	  }
217	
218	  if (needsFullIndexFallback) {
219	    // Last resort only: older/static deployments can lack a manifest or a
220	    // relevant shard even though their legacy complete index still has the row.
221	    rows = await getShardJson<SearchRow[]>('/lexicon/search-index.json', cache).catch(() => []);
222	  }
223	
224	  const atlasByKey = searchRowsByKey(rows);
225	  for (const key of unresolved) {
226	    const atlasRow = keyLookupVariants(key)
227	      .map((variant) => atlasByKey.get(variant))
228	      .find((entry): entry is SearchRow => Boolean(entry));
229	    if (!atlasRow) continue;
230	    const gloss = atlasRow.g ? cleanGloss(atlasRow.g) : '';
231	    resolutions.set(key, {
232	      practice: null,
233	      atlas: {
234	        lemma: atlasRow.l,
235	        slug: atlasRow.s,
236	        // Search-index text can be a dictionary definition. Only retain the
237	        // same concise first-sense labels eligible for practice cards.
238	        gloss: isPhraseGloss(gloss) ? null : gloss,
239	        cefr: atlasRow.c ?? null,
240	      },
241	    });
242	  }
243	  return resolutions;
244	}
