246	function ensureDeckCustomSetCoverage(
247	  deck: PracticeDeckData,
248	  lemmaKeys: string[],
249	  resolutions: ReadonlyMap<string, DeckKeyResolution>,
250	): PracticeDeckData {
251	  if (!deck || !lemmaKeys || lemmaKeys.length === 0) return deck;
252	  const existingIndexLemmas = new Set<string>();
253	  for (const item of deck.index ?? []) {
254	    existingIndexLemmas.add(item.lemmaId.toLocaleLowerCase());
255	    existingIndexLemmas.add(item.lemma.toLocaleLowerCase());
256	  }
257	  const newIndexItems: PracticeIndexItem[] = [];
258	  const newLexemes: PracticeLexeme[] = [];
259	
260	  const clozeByLemma = new Map<string, string[]>();
261	  for (const c of deck.cloze ?? []) {
262	    const key1 = (c.lemmaId || '').toLowerCase();
263	    const key2 = (c.lemma || '').toLowerCase();
264	    if (key1) {
265	      if (!clozeByLemma.has(key1)) clozeByLemma.set(key1, []);
266	      clozeByLemma.get(key1)!.push(c.clozeId);
267	    }
268	    if (key2 && key2 !== key1) {
269	      if (!clozeByLemma.has(key2)) clozeByLemma.set(key2, []);
270	      clozeByLemma.get(key2)!.push(c.clozeId);
271	    }
272	  }
273	
274	  let indexModified = false;
275	  const updatedIndex = (deck.index ?? []).map((item) => {
276	    const keyLower = item.lemmaId.toLowerCase();
277	    const customClozeIds = clozeByLemma.get(keyLower) ?? [];
278	    if (customClozeIds.length === 0) return item;
279	
280	    const mergedClozeIds = Array.from(new Set([...(item.clozeIds ?? []), ...customClozeIds]));
281	    const hasCloze = mergedClozeIds.length > 0;
282	    const modesSet = new Set(item.modes ?? []);
283	    modesSet.add('flashcards');
284	    if (hasCloze) modesSet.add('cloze');
285	
286	    const nextModes = Array.from(modesSet) as PracticeIndexItem['modes'];
287	    const modesChanged = nextModes.length !== (item.modes ?? []).length;
288	    const clozeIdsChanged = mergedClozeIds.length !== (item.clozeIds ?? []).length;
289	    const hasClozeChanged = hasCloze !== item.hasCloze;
290	
291	    if (modesChanged || clozeIdsChanged || hasClozeChanged) {
292	      indexModified = true;
293	      return {
294	        ...item,
295	        clozeIds: mergedClozeIds,
296	        hasCloze,
297	        modes: nextModes,
298	      };
299	    }
300	    return item;
301	  });
302	
303	  let orderCounter = (deck.index ?? []).length + 1;
304	  for (const key of lemmaKeys) {
305	    const keyLower = key.toLowerCase();
306	    if (!existingIndexLemmas.has(keyLower)) {
307	      existingIndexLemmas.add(keyLower);
308	      const cleanKey = cleanDeckKey(key);
309	      const atlas = resolutions.get(key)?.atlas ?? null;
310	      const matchedClozeIds = clozeByLemma.get(keyLower) ?? [];
311	      const hasCloze = matchedClozeIds.length > 0;
312	
313	      // Learner-layout P0-3 / Opus P0-2: an unmatched custom-deck key has no resolved
314	      // practice-core content — claiming the full mode list here promised exercises
315	      // (e.g. a "5" on the Heritage card) that the active session then couldn't
316	      // deliver, landing the learner in an instant empty-mode dead end. Only claim
317	      // the modes this key actually resolves content for; other modes appear once
318	      // real shard data resolves them (same honesty rule as the built shards).
319	      newIndexItems.push({
320	        lemmaId: atlas?.slug ?? key,
321	        lemma: atlas?.lemma ?? cleanKey,
322	        cefr: atlas?.cefr ?? null,
323	        modes: hasCloze ? ['flashcards', 'cloze'] : ['flashcards'],
324	        hasCloze,
325	        clozeIds: matchedClozeIds,
326	        newOrder: orderCounter++,
327	      });
328	
329	      newLexemes.push({
330	        lemmaId: atlas?.slug ?? key,
331	        lemma: atlas?.lemma ?? cleanKey,
332	        lemmaPlain: atlas?.lemma ?? cleanKey,
333	        ipa: null,
334	        gloss: atlas?.gloss ?? cleanKey,
335	        pos: null,
336	        cefr: atlas?.cefr ?? null,
337	        heritage: null,
338	        severity: null,
339	        paradigm: { cases: {} },
340	      });
341	    }
342	  }
343	
344	  if (newIndexItems.length === 0 && !indexModified) return deck;
345	
346	  return {
347	    ...deck,
348	    index: [...updatedIndex, ...newIndexItems],
349	    lexemes: [...(deck.lexemes ?? []), ...newLexemes],
350	  };
351	}
