455	function translateGrammarTerm(ukLabel: string): string {
456	  if (!ukLabel) return '';
457	  const norm = ukLabel.toLowerCase().trim();
458	  const parts = norm.split(/[\s,]+/);
459	  if (norm.includes('відмінок')) {
460	    const caseName = parts.find(p => p !== 'відмінок' && p !== 'і' && CASE_GLOSSES[p]);
461	    const caseEn = caseName ? CASE_GLOSSES[caseName] : '';
462	    const otherParts = parts.filter(p => p !== 'відмінок' && p !== caseName).map(p => CASE_GLOSSES[p] || p);
463	    if (caseEn) {
464	      const caseStr = `${caseEn} case`;
465	      return otherParts.length > 0 ? `${caseStr}, ${otherParts.join(', ')}` : caseStr;
466	    }
467	  }
468	
469	  if (norm.includes('рід')) {
470	    const genderName = parts.find(p => p !== 'рід' && CASE_GLOSSES[p]);
471	    const genderEn = genderName ? CASE_GLOSSES[genderName] : '';
472	    const otherParts = parts.filter(p => p !== 'рід' && p !== genderName).map(p => CASE_GLOSSES[p] || p);
473	    if (genderEn) {
474	      const genderStr = `${genderEn} gender`;
475	      return otherParts.length > 0 ? `${genderStr}, ${otherParts.join(', ')}` : genderStr;
476	    }
477	  }
478	
479	  const translatedParts = parts.map(part => {
480	    if (CASE_GLOSSES[part]) return CASE_GLOSSES[part];
481	    for (const [uk, en] of Object.entries(CASE_GLOSSES)) {
482	      if (part.includes(uk)) return en;
483	    }
484	    return part;
485	  });
486	
487	  return translatedParts.join(', ');
488	}
