795	function isPhraseGloss(label: string): boolean {
796	  const clean = label.replace(/\s+/g, ' ').trim();
797	  // Count alphanumeric tokens (ignoring standalone punctuation) to match the
798	  // Python deck generator's `_meaning_label_word_count` regex exactly, so the
799	  // served deck and this runtime guard never disagree on eligibility.
800	  const wordCount = clean ? (clean.match(/[^\W_]+(?:[-'][^\W_]+)?/gu) || []).length : 0;
801	  return (
802	    !clean ||
803	    clean.length > MEANING_MC_MAX_CHARS ||
804	    wordCount > MEANING_MC_MAX_WORDS ||
805	    clean.includes('?') ||
806	    clean.includes('(') ||
807	    clean.includes(')')
808	  );
809	}
