811	export function isMeaningMcEligible(entry: PracticeLexeme): boolean {
812	  const label = glossLabel(entry);
813	  if (entry.meaningMcEligible === false) return false;
814	  // Judge the CLEAN first-sense label, not the raw multi-sense gloss: a word like
815	  // "dog; hound" has a perfectly concise glossClean ("dog") and must stay eligible.
816	  if (!isEnglishLearnerGloss(label)) return false;
817	  if (isPhraseGloss(label)) return false;
818	  if (FUNCTION_GLOSS_HEADWORDS.has(glossHeadword(entry))) return false;
819	  if (entry.pos && FUNCTION_POS.has(entry.pos.toLocaleLowerCase('en-US'))) return false;
820	  return entry.meaningMcEligible ?? true;
821	}
