1514	/** Deduped fetch for practice and Atlas JSON by URL. Concurrent or repeated callers share the promise. */
1515	async function getShardJson<T>(url: string, cache: Map<string, Promise<unknown>>): Promise<T> {
1516	  let p = cache.get(url) as Promise<T> | undefined;
1517	  if (!p) {
1518	    p = fetch(url).then((res) => {
1519	      if (!res.ok) {
1520	        // Tag the HTTP status so callers can tell an unpublished shard (404,
1521	        // soft-skippable) from a real load fault (network / server error).
1522	        const err = new Error(`Shard fetch failed: ${url}`) as Error & { status?: number };
1523	        err.status = res.status;
1524	        throw err;
1525	      }
1526	      return res.json() as Promise<T>;
1527	    });
1528	    // On failure allow retry next time
1529	    p = p.catch((err) => {
1530	      cache.delete(url);
1531	      throw err;
1532	    });
1533	    cache.set(url, p);
1534	  }
1535	  return p;
1536	}
