40	<script is:inline>
41	(() => {
42	  const MOUNT_SEL = '#lexicon-practice-mount';
43	  const SHELL_ID = 'lexicon-practice-shell';
44	  const FALLBACK_ID = 'lexicon-practice-fallback';
45	  const SUCCESS_SEL = '.lexicon-practice';
46	  const TIMEOUT_MS = 10000;
47	  let done = false;
48	
49	  function hideShell() {
50	    const shell = document.getElementById(SHELL_ID);
51	    if (shell) shell.setAttribute('hidden', '');
52	  }
53	
54	  function showFallback() {
55	    if (done) return;
56	    done = true;
57	    const mount = document.querySelector(MOUNT_SEL);
58	    const fb = document.getElementById(FALLBACK_ID);
59	    hideShell();
60	    if (mount) mount.setAttribute('hidden', '');
61	    if (fb) {
62	      fb.removeAttribute('hidden');
63	    }
64	  }
65	
66	  function markSuccess() {
67	    if (done) return;
68	    done = true;
69	    hideShell();
70	  }
71	
72	  function isOurIsland(target) {
73	    if (!target) return false;
74	    if (target.closest && target.closest(MOUNT_SEL)) return true;
75	    return false;
76	  }
77	
78	  // Listen for astro-island hydration error events (dispatched by Astro runtime on import/hydrate fail)
79	  document.addEventListener('astro:hydration-error', (ev) => {
80	    const d = (ev && ev.detail) || {};
81	    const url = String(d.componentUrl || '');
82	    if (url.includes('LexiconPractice') || isOurIsland(ev.target)) {
83	      showFallback();
84	    }
85	  });
86	
87	  // Listen for successful hydration
88	  document.addEventListener('astro:hydrate', (ev) => {
89	    if (isOurIsland(ev.target)) {
90	      markSuccess();
91	    }
92	  }, true);
93	
94	  function setupObservers() {
95	    const mount = document.querySelector(MOUNT_SEL);
96	    if (!mount) return;
97	
98	    // MutationObserver catches content render quickly on success path
99	    const mo = new MutationObserver(() => {
100	      if (mount.querySelector(SUCCESS_SEL)) {
101	        markSuccess();
102	        mo.disconnect();
103	      }
104	    });
105	    mo.observe(mount, { childList: true, subtree: true });
106	
107	    // Direct listeners on the island element if already in DOM
108	    const island = mount.querySelector('astro-island');
109	    if (island) {
110	      island.addEventListener('astro:hydrate', markSuccess, { once: true });
111	      island.addEventListener('astro:hydration-error', showFallback, { once: true });
112	    }
113	
114	    // If content already present (race or fast path)
115	    if (mount.querySelector(SUCCESS_SEL)) {
116	      markSuccess();
117	    }
118	  }
119	
120	  // Watchdog: ~10s; does not fire if success marker seen; re-checks content before declaring failure
121	  const watchdog = setTimeout(() => {
122	    if (done) return;
123	    const mount = document.querySelector(MOUNT_SEL);
124	    if (mount && mount.querySelector(SUCCESS_SEL)) {
125	      markSuccess();
126	      return;
127	    }
128	    showFallback();
129	  }, TIMEOUT_MS);
130	
131	  function init() {
132	    setupObservers();
133	  }
134	
135	  if (document.readyState === 'loading') {
136	    document.addEventListener('DOMContentLoaded', init, { once: true });
137	  } else {
138	    init();
139	  }
140	})();
141	</script>
