131	/** Progressive mock: selected level (highest) resolves immediately; lower levels return held promises
132	 * so tests can assert first item renders before lowers resolve, and growth after explicit release.
133	 */
134	function mockProgressiveFetch(counts: Partial<Record<CefrLevel, number>>) {
135	  const requested: string[] = [];
136	  const pending: Array<() => void> = [];
137	  const fn = vi.fn(async (input: RequestInfo | URL) => {
138	    const url = String(input);
139	    requested.push(url);
140	    const match = url.match(
141	      /practice-(index|lexemes|cloze|stress|classify|paradigm|synonym|paronym|heritage)\.([ABC][12])\.json/,
142	    );
143	    if (!match) return notFoundResponse();
144	    const kind = match[1] as any;
145	    const level = match[2] as CefrLevel;
146	    const n = counts[level];
147	    if (n === undefined) return notFoundResponse();
148	    const isSelected = level === 'B1' || Object.keys(counts).filter((k) => counts[k as CefrLevel]! > 0).slice(-1)[0] === level; // simplistic: assume B1 target in tests
149	    const makeLex = (lvl: CefrLevel, cnt: number) =>
150	      Array.from({ length: cnt }, (_u, i) =>
151	        lexeme(
152	          `${lvl}-${i}`,
153	          `слово-${lvl}-${i}`,
154	          `gloss ${lvl} ${i}`,
155	          { nominative: `слово-${lvl}-${i}`, accusative: `слово-${lvl}-${i}`, locative: `слово-${lvl}-${i}` },
156	          { cefr: lvl },
157	        ),
158	      );
159	    const lexemes = makeLex(level, n);
160	    const bodyFor = () => {
161	      if (kind === 'index') {
162	        return {
163	          deckVersion: `v-${level}`,
164	          level,
165	          items: lexemes.map((lex, order) => ({
166	            lemmaId: lex.lemmaId,
167	            lemma: lex.lemma,
168	            cefr: level,
169	            modes: ['flashcards', 'matching', 'choice'],
170	            hasCloze: false,
171	            clozeIds: [],
172	            newOrder: order,
173	          })),
174	        };
175	      }
176	      if (kind === 'lexemes') return { deckVersion: `v-${level}`, level, lexemes };
177	      return { [kind]: [] };
178	    };
179	    if (level === 'B1') {
180	      return okJson(bodyFor());
181	    }
182	    // lower held until released
183	    return new Promise<Response>((resolve) => {
184	      pending.push(() => resolve(okJson(bodyFor())));
185	    });
186	  });
187	  return {
188	    fn,
189	    requested,
190	    releaseLowers: () => {
191	      pending.forEach((r) => r());
192	      pending.length = 0;
193	    },
194	    pendingCount: () => pending.length,
195	  };
196	}
