import { beforeEach, describe, expect, test, vi } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import LexiconPractice from '@site/src/components/LexiconPractice';
import { LEARNER_LEVEL_STORAGE_KEY, type CefrLevel } from '@site/src/lib/lexicon/levels';
import { SRS_STORAGE_KEY } from '@site/src/lib/lexicon/srs';
import type { PracticeLexeme } from '@site/src/lib/lexicon/srs';
import type { DailyWord } from '@site/src/lib/lexicon/daily';

function okJson(body: unknown): Response {
  return { ok: true, json: async () => body } as unknown as Response;
}
function notFoundResponse(): Response {
  return { ok: false, status: 404, json: async () => ({}) } as unknown as Response;
}
function lexeme(lemmaId: string, lemma: string, gloss: string, cefr: string): PracticeLexeme {
  return {
    lemmaId,
    lemma,
    lemmaPlain: lemma,
    gloss,
    ipa: null,
    pos: 'noun',
    cefr,
    heritage: 'native',
    severity: 'standard',
    paradigm: { cases: { nominative: { singular: lemma } } },
  } as unknown as PracticeLexeme;
}
function mockShardFetch(counts: Partial<Record<CefrLevel, number>>) {
  const fn = vi.fn(async (input: RequestInfo | URL) => {
    const url = String(input);
    if (url.includes('daily-pool.json')) {
      const pool: DailyWord[] = Object.entries(counts).flatMap(([level, n]) =>
        Array.from({ length: n ?? 0 }, (_u, i) => ({
          lemma: `слово-${level}-${i}`,
          slug: `${level}-${i}`,
          gloss: `gloss ${level} ${i}`,
          cefr: level,
        })),
      );
      return okJson(pool);
    }
    const match = url.match(
      /practice-(index|lexemes|cloze|stress|classify|paradigm|synonym|paronym|heritage|antonym)\.([ABC][12])\.json/,
    );
    if (!match) return notFoundResponse();
    const kind = match[1];
    const level = match[2] as CefrLevel;
    const n = counts[level];
    if (n === undefined) return notFoundResponse();
    if (kind !== 'index' && kind !== 'lexemes') return okJson({ [kind]: [] });
    const lexemes = Array.from({ length: n }, (_u, i) =>
      lexeme(`${level}-${i}`, `слово-${level}-${i}`, `gloss ${level} ${i}`, level),
    );
    if (kind === 'index') {
      return okJson({
        deckVersion: `v-${level}`,
        level,
        items: lexemes.map((lex, order) => ({
          lemmaId: lex.lemmaId,
          lemma: lex.lemma,
          cefr: level,
          modes: ['flashcards', 'matching', 'choice'],
          hasCloze: false,
          clozeIds: [],
          newOrder: order,
        })),
      });
    }
    return okJson({ deckVersion: `v-${level}`, level, lexemes });
  });
  return { fn };
}

describe('scratch #6723 chip flow', () => {
  beforeEach(() => {
    localStorage.clear();
    document.documentElement.dataset.chromeLocale = 'en';
  });

  test('level switch mid-session → accept → home → chip shows new level', async () => {
    localStorage.setItem(LEARNER_LEVEL_STORAGE_KEY, 'A1');
    const { fn } = mockShardFetch({ A1: 15, B1: 15 });
    vi.spyOn(globalThis, 'fetch').mockImplementation(fn);
    const user = userEvent.setup();
    render(<LexiconPractice />);

    // start a mixed session
    const start = await screen.findByTestId('practice-start-session');
    await user.click(start);
    await screen.findByTestId('practice-session-progress');

    // click B1 → offer → accept
    await user.click(screen.getByRole('button', { name: 'B1' }));
    const accept = await screen.findByTestId('practice-switch-session-accept');
    await user.click(accept);

    // session may restart; go home
    await waitFor(() => expect(screen.getByTestId('practice-session-progress')).toBeInTheDocument());
    const home = document.querySelector<HTMLButtonElement>('button.stage-back')!;
    await user.click(home);

    const chip = await screen.findByTestId('practice-active-deck-chip');
    // eslint-disable-next-line no-console
    console.log('CHIP TEXT:', chip.textContent);
    expect(chip).toHaveTextContent(/All Words \(B1\)/);
  });
});

